// MAP - Normalize incoming reservation data to standard format
// Supports: direct JSON, form data, Google Forms

const input = $input.first().json;
const body = input.body || input;

// Extract fields with fallbacks for different input formats
const customerName = body.customer_name || body.name || body.nome || '';
const phone = body.phone || body.telefono || body.phone_number || '';
const date = body.date || body.data || body.reservation_date || '';
const time = body.time || body.ora || body.reservation_time || '';
const covers = parseInt(body.covers || body.coperti || body.guests || body.persone || '2');
const notes = body.notes || body.note || '';
const channel = body.channel || body.canale || 'website';
const language = body.language || body.lingua || 'it';

// Normalize phone to E.164
let phoneE164 = phone.replace(/[\s\-\(\)]/g, '');
if (phoneE164.startsWith('00')) phoneE164 = '+' + phoneE164.substring(2);
if (!phoneE164.startsWith('+')) phoneE164 = '+39' + phoneE164;

// Generate reservation ID
const reservationId = 'RES-' + Date.now().toString(36).toUpperCase();

// Build reservation datetime
const reservationDatetime = date + 'T' + time + ':00';

return [{
  json: {
    reservation_id: reservationId,
    customer_name: customerName.trim(),
    phone_e164: phoneE164,
    reservation_date: date,
    reservation_time: time,
    reservation_datetime: reservationDatetime,
    covers: covers,
    notes: notes,
    source_channel: channel,
    language: language,
    status: 'pending_confirmation',
    created_at: new Date().toISOString(),
    reminder_sent: 'no',
    confirmation_message_id: '',
    error_code: '',
    error_message: ''
  }
}];

// VAL - Validate required fields and business rules

const item = $input.first().json;
const errors = [];

// Required fields
if (!item.customer_name || item.customer_name.length < 2) {
  errors.push('customer_name is required (min 2 chars)');
}

// Phone E.164 validation
const phoneRegex = /^\+[1-9]\d{7,14}$/;
if (!phoneRegex.test(item.phone_e164)) {
  errors.push('phone must be valid E.164 format (e.g., +393401234567)');
}

// Date validation
const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
if (!dateRegex.test(item.reservation_date)) {
  errors.push('date must be YYYY-MM-DD format');
}

// Time validation
const timeRegex = /^\d{2}:\d{2}$/;
if (!timeRegex.test(item.reservation_time)) {
  errors.push('time must be HH:MM format');
}

// Date must be today or future
const resDate = new Date(item.reservation_datetime);
const now = new Date();
if (resDate < now) {
  errors.push('reservation date must be in the future');
}

// Covers range
if (item.covers < 1 || item.covers > 50) {
  errors.push('covers must be between 1 and 50');
}

return [{
  json: {
    ...item,
    is_valid: errors.length === 0,
    validation_errors: errors
  }
}];
